import numpy as np
from scipy.optimize import least_squares
t=df['t'].values;A=df['A'].values;y=df['dA_dt'].values
V=np.var(y)
Bt=np.column_stack([np.ones_like(t),t,t**2,1/t,1/t**2,np.exp(-t)])
def resid(q, kind):
    if kind==0:
        K=q[0]+q[1]*t; n=q[2]; h=1/(1+(np.abs(A)/np.abs(K))**n)
    elif kind==1:
        K=q[0]+q[1]*t; n=q[2]; h=np.exp(-A/np.abs(K))*A**n
    else:
        k=np.exp(q[0]+q[1]*t); n=q[2]; h=1-np.exp(-k*A**n)
    X=np.column_stack([Bt, Bt*h[:,None]])
    c,*_=np.linalg.lstsq(X,y,rcond=None)
    return y-X@c
out=[]
rng=np.random.default_rng(5)
for kind in [0,1,2]:
